// set species codes to access clade (conifer/hardwood) parameters
// these are arbitrary and can be changed if new information for these species is found
std::array<int,2> clade_defaults = { 299, 990 };


MCWPARMS &get_mcw_parms( int spcd, 
                         bool allow_donor, 
                         bool allow_none ) 
{
    MCWPARMS &mcw_data = mcw_parms[0];
    std::stringstream ss;

    // look up species in the MCW parameter table.
    try {
        mcw_data = mcw_parms.at( spcd );
    } catch( std::out_of_range &e ) {
        
        // species not found in parameter table, default to conifer/hardwood defaults
        try {
            mcw_data = mcw_parms.at( spcd < 300 ? clade_defaults[0] :clade_defaults[1]  );
        } catch( std::out_of_range &e2 ) {
            ss << "No MCW data for " << spcd << " and default species.";
            throw( ss.str() );
        }
    }  
    
    if( !allow_donor && mcw_data.extension_route != "direct" ) {
        ss << "allow_donor is false and spcd " << spcd << " is not among direct fits.";
        throw( ss.str() );
    }

    if( !allow_none && mcw_data.confidence == "none" ) {
        ss << spcd << " has no defensible crown model and allow_none is false.";
        throw( ss.str() );
    }
                   
    return( mcw_data );
}


std::vector<double> compute_mcw( const std::vector<int> &fia,
                                 const std::vector<double> &dbh,
                                 const bool imperial_units,
                                 const bool allow_donor,
                                 const bool allow_none,
                                 const bool hold_domain,
                                 const bool apply_ceiling )
{
    MCWPARMS mcw_data;
    size_t n = fia.size();
    std::vector<double> mcw_hat( n, 0.0 );

    for( size_t i = 0; i < n; ++i )
    {
        mcw_data = get_mcw_parms( fia[i], allow_donor, allow_none ); 

        double d = dbh[i];
        if( !imperial_units ) 
            d /= 2.54;
        
        if( hold_domain && d > mcw_data.dbh_max_fit ) 
            d = mcw_data.dbh_max_fit;

        mcw_hat[i] = mcw_data.a1 * std::pow( d,  mcw_data.a2 );  
        
        if( apply_ceiling && mcw_hat[i] > mcw_data.cw_ceiling ) 
            mcw_hat[i] = mcw_data.cw_ceiling;

        if( !imperial_units ) 
            mcw_hat[i] /= 3.2808;
    }

    return mcw_hat;

}


//////////////////////////////////////////////////////////////////////////////////////////////////


// The bounded Beta ratio, evaluated on the same diameter the MCW curve saw so that lcw is flat above dbh_max_fit 
// exactly where mcw is.

double cw_ratio( double dbh,
                 double cr,
                 double ratio_intercept,
                 double ratio_cr,
                 double ratio_dbh )
{
    
    double eta = ratio_intercept + ratio_cr * cr + ratio_dbh * dbh;
    
    double ratio = 1.0 / (1.0 + std::exp( -eta ) );    
 
    return ratio;   
}

     
// Largest crown width, the stand grown crown width, for CONUS tree species.
// lcw is not fit as its own allometry. It is a bounded fraction of the maximum
// crown width envelope. (Weiskittel, Marshall, Johnson 2026)

std::vector<double> compute_lcw( const std::vector<int> &fia,
                                 const std::vector<double> &dbh,
                                 const std::vector<double> &cr,
                                 const bool imperial_units,
                                 const bool allow_donor,
                                 const bool allow_none,
                                 const bool hold_domain,
                                 const bool apply_ceiling )
{
    double to_imperial = imperial_units ? 1.0 : 0.393701;
    
    std::vector<double> mcw_hat = compute_mcw( fia, dbh, imperial_units, allow_donor, allow_none, hold_domain, apply_ceiling );

    std::vector<double> lcw_hat;
 
    for( size_t i = 0; i < fia.size(); ++i )
    {
        double dbh_t = dbh[i] * to_imperial;
        MCWPARMS mcw_data = get_mcw_parms( fia[i], allow_donor, allow_none );
        
        if( hold_domain && dbh_t > mcw_data.dbh_max_fit ) 
            dbh_t = mcw_data.dbh_max_fit;
        
        double ratio = cw_ratio( dbh_t, cr[i], mcw_data.ratio_intercept, mcw_data.ratio_cr, mcw_data.ratio_dbh );
        
        lcw_hat.push_back( ratio * mcw_hat[i] );
    }
    
    return lcw_hat;
}
